from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    paren_string = paren_string.replace(" ", "")  # Step 1: Remove spaces from the input string
    clusters = []  # Initialize a list to store isolated clusters

    stack = []  # Initialize a stack to keep track of opening parentheses
    start = 0  # Initialize a variable to keep track of the start index of a cluster

    for i, char in enumerate(paren_string):
        if char == '(':
            stack.append(i)  # Step 2: Identify the opening parentheses
            if len(stack) == 1:
                start = i  # Update the start index of a new cluster

        elif char == ')':
            if len(stack) == 1:
                clusters.append(paren_string[start:i+1])  # Step 3: Isolate each cluster
            stack.pop()  # Step 2: Identify the closing parentheses

    return clusters  # Step 4: Return the isolated clusters in a list form

# Test the function
print(separate_paren_groups('( ) (( )) (( )( ))'))  # Output: ['()', '(())', '(()())']

